import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.BTjPRYTP.js";const g=JSON.parse('{"title":"Vehicle Tracking & Live Map","description":"","frontmatter":{},"headers":[],"relativePath":"features/vehicle-tracking.md","filePath":"features/vehicle-tracking.md"}'),s={name:"features/vehicle-tracking.md"};function n(o,t,d,l,h,c){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="vehicle-tracking-live-map" tabindex="-1">Vehicle Tracking &amp; Live Map <a class="header-anchor" href="#vehicle-tracking-live-map" aria-label="Permalink to &quot;Vehicle Tracking &amp; Live Map&quot;">​</a></h1><p>TeslaSync provides comprehensive vehicle tracking with real-time GPS positioning, drive history, and an interactive map.</p><h2 id="live-map" tabindex="-1">Live Map <a class="header-anchor" href="#live-map" aria-label="Permalink to &quot;Live Map&quot;">​</a></h2><p>The <strong>Live Map</strong> page (<code>/live</code>) displays all your vehicles on an interactive <a href="https://leafletjs.com/" target="_blank" rel="noreferrer">Leaflet</a> map with real-time position updates.</p><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Real-time GPS markers</strong> — Vehicle positions update via SSE every 15 seconds</li><li><strong>Vehicle info popups</strong> — Click a marker to see battery, speed, range, and state</li><li><strong>Drive route replay</strong> — View historical drive routes overlaid on the map</li><li><strong>Heatmap layer</strong> — Toggle a heatmap showing frequently visited locations (using <code>leaflet.heat</code>)</li><li><strong>Multiple tile layers</strong> — Switch between standard, satellite, and dark map styles</li><li><strong>Auto-center</strong> — Map automatically centers on your fleet&#39;s bounding box</li></ul><h3 id="map-controls" tabindex="-1">Map Controls <a class="header-anchor" href="#map-controls" aria-label="Permalink to &quot;Map Controls&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Action</th></tr></thead><tbody><tr><td><strong>Zoom</strong></td><td>Mouse wheel or +/- buttons</td></tr><tr><td><strong>Pan</strong></td><td>Click and drag</td></tr><tr><td><strong>Center on vehicle</strong></td><td>Click the vehicle marker</td></tr><tr><td><strong>Toggle heatmap</strong></td><td>Button in the map toolbar</td></tr><tr><td><strong>Toggle route</strong></td><td>Select a drive to overlay its route</td></tr><tr><td><strong>Full screen</strong></td><td>Button in the top-right corner</td></tr></tbody></table><h3 id="vehicle-markers" tabindex="-1">Vehicle Markers <a class="header-anchor" href="#vehicle-markers" aria-label="Permalink to &quot;Vehicle Markers&quot;">​</a></h3><p>Each vehicle is shown as a marker on the map with visual indicators:</p><table tabindex="0"><thead><tr><th>Marker State</th><th>Color</th><th>Description</th></tr></thead><tbody><tr><td><strong>Online/Parked</strong></td><td>Green</td><td>Vehicle is awake and stationary</td></tr><tr><td><strong>Driving</strong></td><td>Blue (animated)</td><td>Vehicle is moving, marker pulses</td></tr><tr><td><strong>Charging</strong></td><td>Amber</td><td>Vehicle is plugged in and charging</td></tr><tr><td><strong>Asleep</strong></td><td>Gray</td><td>Vehicle is in sleep mode</td></tr><tr><td><strong>Offline</strong></td><td>Red</td><td>Vehicle is unreachable</td></tr></tbody></table><h2 id="vehicle-detail-page" tabindex="-1">Vehicle Detail Page <a class="header-anchor" href="#vehicle-detail-page" aria-label="Permalink to &quot;Vehicle Detail Page&quot;">​</a></h2><p>The <strong>Vehicle Detail</strong> page (<code>/vehicles/:id</code>) provides a deep dive into a single vehicle:</p><h3 id="vehicle-overview" tabindex="-1">Vehicle Overview <a class="header-anchor" href="#vehicle-overview" aria-label="Permalink to &quot;Vehicle Overview&quot;">​</a></h3><ul><li><strong>Display name</strong>, model, VIN, exterior color, wheel type</li><li><strong>Current state</strong> — Online, asleep, driving, charging</li><li><strong>Battery level</strong> with visual gauge</li><li><strong>Rated and ideal range</strong> in configured units (km/miles)</li><li><strong>Odometer</strong> reading</li><li><strong>Software version</strong> with update status</li></ul><h3 id="vehicle-visualization" tabindex="-1">Vehicle Visualization <a class="header-anchor" href="#vehicle-visualization" aria-label="Permalink to &quot;Vehicle Visualization&quot;">​</a></h3><p>The <code>TeslaCarViz</code> component renders a visual representation of the vehicle showing:</p><ul><li>Door lock status (locked/unlocked icons)</li><li>Climate on/off indicator</li><li>Sentry mode status</li><li>Frunk/trunk open status</li><li>Tire pressure indicators (if available)</li><li>Charging port status</li></ul><h3 id="current-state-snapshot" tabindex="-1">Current State Snapshot <a class="header-anchor" href="#current-state-snapshot" aria-label="Permalink to &quot;Current State Snapshot&quot;">​</a></h3><p>Live telemetry data displayed in a grid:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Source</th></tr></thead><tbody><tr><td>Battery Level</td><td><code>battery_level</code> (0–100%)</td></tr><tr><td>Rated Range</td><td><code>rated_range</code> (km)</td></tr><tr><td>Speed</td><td><code>speed</code> (km/h)</td></tr><tr><td>Power</td><td><code>power</code> (kW, negative = regen)</td></tr><tr><td>Inside Temp</td><td><code>inside_temp</code> (°C)</td></tr><tr><td>Outside Temp</td><td><code>outside_temp</code> (°C)</td></tr><tr><td>Climate</td><td><code>is_climate_on</code> (on/off)</td></tr><tr><td>Locked</td><td><code>is_locked</code> (yes/no)</td></tr><tr><td>Sentry Mode</td><td><code>sentry_mode</code> (on/off)</td></tr><tr><td>Charging</td><td><code>is_charging</code> (yes/no)</td></tr><tr><td>GPS</td><td><code>latitude</code>, <code>longitude</code></td></tr></tbody></table><h3 id="gps-position-history" tabindex="-1">GPS Position History <a class="header-anchor" href="#gps-position-history" aria-label="Permalink to &quot;GPS Position History&quot;">​</a></h3><p>View historical positions for a vehicle within a date range:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/vehicles/{vehicleID}/positions?start=2024-01-01&amp;end=2024-01-31</span></span></code></pre></div><p>The response includes timestamped positions that can be plotted on the map for route visualization.</p><h2 id="drives" tabindex="-1">Drives <a class="header-anchor" href="#drives" aria-label="Permalink to &quot;Drives&quot;">​</a></h2><p>The <strong>Drives</strong> page (<code>/drives</code>) shows a complete history of all drives across your fleet.</p><h3 id="drive-list" tabindex="-1">Drive List <a class="header-anchor" href="#drive-list" aria-label="Permalink to &quot;Drive List&quot;">​</a></h3><p>A sortable, filterable table showing:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Vehicle</strong></td><td>Display name</td></tr><tr><td><strong>Date</strong></td><td>Start date and time</td></tr><tr><td><strong>Duration</strong></td><td>Drive duration in minutes</td></tr><tr><td><strong>Distance</strong></td><td>Distance traveled (km/mi)</td></tr><tr><td><strong>Start → End</strong></td><td>Start and end addresses</td></tr><tr><td><strong>Battery</strong></td><td>Start and end battery levels</td></tr><tr><td><strong>Range</strong></td><td>Start and end rated range</td></tr><tr><td><strong>Max Speed</strong></td><td>Maximum speed during the drive</td></tr><tr><td><strong>Efficiency</strong></td><td>Wh/km or Wh/mi</td></tr></tbody></table><h3 id="drive-detail" tabindex="-1">Drive Detail <a class="header-anchor" href="#drive-detail" aria-label="Permalink to &quot;Drive Detail&quot;">​</a></h3><p>Click any drive to see the <strong>Drive Detail</strong> page (<code>/drives/:id</code>) with:</p><ul><li><strong>Route map</strong> — The drive path plotted on a Leaflet map</li><li><strong>Speed chart</strong> — Speed over time (Recharts line chart)</li><li><strong>Power chart</strong> — Power consumption over time (positive = consumption, negative = regen)</li><li><strong>Elevation chart</strong> — Elevation profile of the route</li><li><strong>Temperature</strong> — Inside/outside temperature during the drive</li><li><strong>Battery drain</strong> — Battery level from start to end</li></ul><h3 id="drive-detection" tabindex="-1">Drive Detection <a class="header-anchor" href="#drive-detection" aria-label="Permalink to &quot;Drive Detection&quot;">​</a></h3><p>The backend worker automatically detects drives by monitoring:</p><ol><li><strong>Start condition:</strong> Vehicle speed &gt; 0 for consecutive polls</li><li><strong>End condition:</strong> Vehicle speed = 0 for consecutive polls</li><li>A drive record is created with start/end positions, addresses, and telemetry</li></ol><h2 id="remote-commands" tabindex="-1">Remote Commands <a class="header-anchor" href="#remote-commands" aria-label="Permalink to &quot;Remote Commands&quot;">​</a></h2><p>From the <strong>Commands</strong> page (<code>/commands</code>) or the vehicle detail page, you can send remote commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><strong>Lock</strong></td><td>Lock all doors</td></tr><tr><td><strong>Unlock</strong></td><td>Unlock all doors</td></tr><tr><td><strong>Climate On</strong></td><td>Start climate control</td></tr><tr><td><strong>Climate Off</strong></td><td>Stop climate control</td></tr><tr><td><strong>Start Charge</strong></td><td>Begin charging</td></tr><tr><td><strong>Stop Charge</strong></td><td>Stop charging</td></tr><tr><td><strong>Open Frunk</strong></td><td>Open the front trunk</td></tr><tr><td><strong>Open Trunk</strong></td><td>Open the rear trunk</td></tr><tr><td><strong>Sentry On</strong></td><td>Enable sentry mode</td></tr><tr><td><strong>Sentry Off</strong></td><td>Disable sentry mode</td></tr><tr><td><strong>Horn</strong></td><td>Honk the horn</td></tr><tr><td><strong>Flash</strong></td><td>Flash the headlights</td></tr><tr><td><strong>Set Speed Limit</strong></td><td>Set valet speed limit</td></tr><tr><td><strong>Wake</strong></td><td>Wake the vehicle from sleep</td></tr></tbody></table><p>Commands are sent via:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/vehicles/{vehicleID}/command</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{ &quot;command&quot;: &quot;lock&quot; }</span></span></code></pre></div><h2 id="mqtt-integration" tabindex="-1">MQTT Integration <a class="header-anchor" href="#mqtt-integration" aria-label="Permalink to &quot;MQTT Integration&quot;">​</a></h2><p>All vehicle telemetry is published to MQTT for integration with home automation systems like Home Assistant:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Topic: teslasync/vehicles/{VIN}/{metric}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>  teslasync/vehicles/5YJ3E1EA5KF123456/battery_level → 85</span></span>
<span class="line"><span>  teslasync/vehicles/5YJ3E1EA5KF123456/latitude → 37.7749</span></span>
<span class="line"><span>  teslasync/vehicles/5YJ3E1EA5KF123456/speed → 0</span></span>
<span class="line"><span>  teslasync/vehicles/5YJ3E1EA5KF123456/is_locked → true</span></span></code></pre></div><p>Subscribe with any MQTT client:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosquitto_sub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1883</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;teslasync/vehicles/#&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><h2 id="vehicle-state-timeline" tabindex="-1">Vehicle State Timeline <a class="header-anchor" href="#vehicle-state-timeline" aria-label="Permalink to &quot;Vehicle State Timeline&quot;">​</a></h2><p>The <strong>Timeline</strong> page (<code>/timeline</code>) shows state transitions over time:</p><ul><li>When the vehicle went online, asleep, or offline</li><li>Driving and charging sessions overlaid</li><li>Color-coded blocks for easy visualization</li></ul><p>API endpoints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/states/timeline?vehicle_id=123&amp;start=2024-01-01&amp;end=2024-01-31</span></span>
<span class="line"><span>GET /api/v1/states/summary?vehicle_id=123</span></span>
<span class="line"><span>GET /api/v1/states/daily?vehicle_id=123</span></span></code></pre></div>`,51)])])}const u=e(s,[["render",n]]);export{g as __pageData,u as default};
